  `author_name` varchar(100) NOT NULL COMMENT '作者名稱',
  `view_count` int DEFAULT '0' COMMENT '閱讀次數',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '創建時間',
