CREATE TABLE `divination_note` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `history_id` bigint NOT NULL,
  `user_id` bigint NOT NULL,
  `note` text COLLATE utf8mb4_unicode_ci,
  `is_accurate` tinyint(1) DEFAULT NULL COMMENT '0=不準, 1=準, NULL=未評價',
  `created_at` datetime NOT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `history_id` (`history_id`),
  KEY `user_id` (`user_id`),
  CONSTRAINT `divination_note_ibfk_1` FOREIGN KEY (`history_id`) REFERENCES `divination_history` (`id`) ON DELETE CASCADE,
  CONSTRAINT `divination_note_ibfk_2` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=8 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
