CREATE TABLE `japan_poem` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `number` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `fortune_level` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
