  `wish` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `illness` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `waiting_person` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `lost_item` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `life_events` varchar(300) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=103 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
